SELECT



ORDER BY cp.published_time DESC, cp.id DESC
LIMIT #{limit}

SELECT



ORDER BY IFNULL(cp.ranking, 999999) ASC, cp.view_count DESC, cp.id DESC
LIMIT #{limit}

SELECT




    AND cc.category_code = #{category}


    AND (cp.title LIKE CONCAT('%', #{keyword}, '%') OR cp.summary LIKE CONCAT('%', #{keyword}, '%'))


    AND EXISTS (
    SELECT 1 FROM content_post_tag pt
    JOIN content_tag t ON t.id = pt.tag_id AND t.status = 1
    WHERE pt.post_id = cp.id AND t.tag_name = #{tag}
    )



        ORDER BY cp.view_count DESC, cp.id DESC


        ORDER BY cp.published_time DESC, cp.id DESC
